-- AW21-24 P1 annual-reserve top-up draft v1.
-- DRAFT ONLY: no learner-visible content and no existing evidence mutation.
-- Exact delta per skill: +2 diagnostics, +2 delayed retests, +1 mixed/transfer.
-- Correct-option positions are balanced and explicitly reject cyclic sequential patterns.
begin;
set local lock_timeout='3s';
set local statement_timeout='90s';

do $preflight$
begin
  if not exists(select 1 from private.exam_prep_program_versions
    where program_key='math_as_p1_p5' and version_key='p1_p5_canonical_v1_0' and status='active')
  then raise exception 'aw21_24_annual_reserve_p1_draft canonical program missing'; end if;
  if exists(select 1 from private.exam_prep_content_versions where id=4823 and content_version<>'p1_aw21_24_annual_reserve_topup_draft_v1')
     or exists(select 1 from private.exam_prep_question_content_meta where id between 59532 and 59581 and content_version_id<>4823)
  then raise exception 'aw21_24_annual_reserve_p1_draft reserved id collision'; end if;
  if (select count(*) from private.exam_prep_question_content_meta m join private.exam_prep_content_versions cv on cv.id=m.content_version_id
      where cv.status='published' and m.lifecycle_state in ('published','reserve')
        and m.primary_skill_code=any(array['P1-COO-05','P1-COO-06','P1-DIF-05','P1-DIF-06','P1-DIF-07','P1-INT-01','P1-INT-02','P1-INT-03','P1-INT-04','P1-INT-05'])
        and m.reserve_role='diagnostic')<>10
     or (select count(*) from private.exam_prep_question_content_meta m join private.exam_prep_content_versions cv on cv.id=m.content_version_id
      where cv.status='published' and m.lifecycle_state in ('published','reserve')
        and m.primary_skill_code=any(array['P1-COO-05','P1-COO-06','P1-DIF-05','P1-DIF-06','P1-DIF-07','P1-INT-01','P1-INT-02','P1-INT-03','P1-INT-04','P1-INT-05'])
        and m.reserve_role='retest')<>20
     or (select count(*) from private.exam_prep_question_content_meta m join private.exam_prep_content_versions cv on cv.id=m.content_version_id
      where cv.status='published' and m.lifecycle_state in ('published','reserve')
        and m.primary_skill_code=any(array['P1-COO-05','P1-COO-06','P1-DIF-05','P1-DIF-06','P1-DIF-07','P1-INT-01','P1-INT-02','P1-INT-03','P1-INT-04','P1-INT-05'])
        and m.reserve_role='mixed')<>10
  then raise exception 'aw21_24_annual_reserve_p1_draft baseline reserve depth changed'; end if;
end
$preflight$;

insert into private.exam_prep_content_versions(id,program_version_id,content_version,component_code,release_label,status,source_policy,source_level)
overriding system value
select 4823,pv.id,'p1_aw21_24_annual_reserve_topup_draft_v1','P1','P1 AW21-24 annual reserve top-up draft v1','draft',
 'Original iClub-authored annual reserve expansion. Official Cambridge 9709 scope controls learning objectives; Complete Pure Mathematics 1 is mapping/explanation support only. No protected Cambridge/coursebook question, solution, mark-scheme wording or diagram is copied. Independent academic, trilingual, technical, originality and reserve-isolation QA is required before publication.',3
from private.exam_prep_program_versions pv
where pv.program_key='math_as_p1_p5' and pv.version_key='p1_p5_canonical_v1_0' and pv.status='active'
on conflict(program_version_id,content_version) do nothing;

with src(content_key,skill_code,reserve_role,difficulty,qtype,q_en,opts_en,answer,exp_en,q_ru,opts_ru,exp_ru,q_uz,opts_uz,exp_uz,time_limit) as (values
('P1COO05-D02','P1-COO-05','diagnostic','medium','mcq','The circle x²+y²−6x+4y−12=0 is written in centre-radius form. Which centre and radius are correct?','["centre (−3,2), radius 5","centre (3,−2), radius 5","centre (3,2), radius √12","centre (−3,−2), radius 25"]','B','Completing the square gives (x−3)²+(y+2)²=25, so the centre is (3,−2) and the radius is 5.','Окружность x²+y²−6x+4y−12=0 записывают в форме с центром и радиусом. Какие центр и радиус верны?','["центр (−3,2), радиус 5","центр (3,−2), радиус 5","центр (3,2), радиус √12","центр (−3,−2), радиус 25"]','После выделения квадратов получаем (x−3)²+(y+2)²=25, поэтому центр (3,−2), радиус 5.','x²+y²−6x+4y−12=0 aylana markaz-radius ko‘rinishiga keltiriladi. Qaysi markaz va radius to‘g‘ri?','["markaz (−3,2), radius 5","markaz (3,−2), radius 5","markaz (3,2), radius √12","markaz (−3,−2), radius 25"]','Kvadratlarni to‘ldirsak (x−3)²+(y+2)²=25 bo‘ladi, demak markaz (3,−2), radius 5.',70),
('P1COO05-D03','P1-COO-05','diagnostic','medium','mcq','The line y=2x−1 meets the circle x²+y²=25. Which quadratic in x is obtained by substitution?','["5x²−4x−24=0","5x²−4x−26=0","3x²−4x−24=0","5x²−2x−24=0"]','A','Substitute y=2x−1: x²+(2x−1)²=25, so 5x²−4x−24=0.','Прямая y=2x−1 пересекает окружность x²+y²=25. Какое квадратное уравнение по x получается после подстановки?','["5x²−4x−24=0","5x²−4x−26=0","3x²−4x−24=0","5x²−2x−24=0"]','Подставляем y=2x−1: x²+(2x−1)²=25, поэтому 5x²−4x−24=0.','y=2x−1 chiziq x²+y²=25 aylana bilan kesishadi. Qo‘yishdan keyin x bo‘yicha qaysi kvadrat tenglama hosil bo‘ladi?','["5x²−4x−24=0","5x²−4x−26=0","3x²−4x−24=0","5x²−2x−24=0"]','y=2x−1 ni qo‘yamiz: x²+(2x−1)²=25, demak 5x²−4x−24=0.',70),
('P1COO05-R03','P1-COO-05','retest','medium','input','A circle has centre (1,−2) and radius 5. It meets the line y=2 at two points. Enter the positive x-coordinate of an intersection.','[]','4','(x−1)²+(2+2)²=25 gives (x−1)²=9, so x=4 or −2. The positive value is 4.','Окружность имеет центр (1,−2) и радиус 5. Она пересекает прямую y=2 в двух точках. Введите положительную x-координату точки пересечения.','[]','(x−1)²+(2+2)²=25 даёт (x−1)²=9, поэтому x=4 или −2. Положительное значение равно 4.','Aylananing markazi (1,−2), radiusi 5. U y=2 chiziqni ikki nuqtada kesadi. Kesishish nuqtasining musbat x-koordinatasini kiriting.','[]','(x−1)²+(2+2)²=25 dan (x−1)²=9, shuning uchun x=4 yoki −2. Musbat qiymat 4.',70),
('P1COO05-R04','P1-COO-05','retest','hard','mcq','The line y=x+1 intersects the circle x²+y²=13. What are the x-coordinates of the two intersection points?','["3 and −2","1 and −4","2 and −3","2 and −2"]','C','Substitution gives x²+(x+1)²=13, hence x²+x−6=0=(x−2)(x+3). So x=2 or −3.','Прямая y=x+1 пересекает окружность x²+y²=13. Каковы x-координаты двух точек пересечения?','["3 и −2","1 и −4","2 и −3","2 и −2"]','После подстановки x²+(x+1)²=13, то есть x²+x−6=0=(x−2)(x+3). Поэтому x=2 или −3.','y=x+1 chiziq x²+y²=13 aylanani kesadi. Ikki kesishish nuqtasining x-koordinatalari qaysi?','["3 va −2","1 va −4","2 va −3","2 va −2"]','Qo‘yishdan x²+(x+1)²=13, ya’ni x²+x−6=0=(x−2)(x+3). Demak x=2 yoki −3.',80),
('P1COO05-M02','P1-COO-05','mixed','hard','input','The circle (x−2)²+(y−1)²=25 is cut by the vertical line x=5. Enter the sum of the y-coordinates of the two intersection points.','[]','2','With x=5, 9+(y−1)²=25, so y−1=±4 and y=5 or −3. Their sum is 2.','Окружность (x−2)²+(y−1)²=25 пересекается вертикальной прямой x=5. Введите сумму y-координат двух точек пересечения.','[]','При x=5: 9+(y−1)²=25, поэтому y−1=±4 и y=5 или −3. Их сумма равна 2.','(x−2)²+(y−1)²=25 aylana x=5 vertikal chiziq bilan kesishadi. Ikki kesishish nuqtasi y-koordinatalari yig‘indisini kiriting.','[]','x=5 bo‘lsa, 9+(y−1)²=25. Demak y−1=±4 va y=5 yoki −3. Yig‘indi 2.',85),
('P1COO06-D02','P1-COO-06','diagnostic','medium','mcq','Which horizontal lines are tangent to the circle x²+y²=25?','["y=5 and y=−5","y=25 and y=−25","y=0 only","y=√5 and y=−√5"]','A','A horizontal tangent is a radius 5 above or below the centre (0,0), so y=±5.','Какие горизонтальные прямые касаются окружности x²+y²=25?','["y=5 и y=−5","y=25 и y=−25","только y=0","y=√5 и y=−√5"]','Горизонтальная касательная находится на расстоянии радиуса 5 выше или ниже центра (0,0), поэтому y=±5.','Qaysi gorizontal chiziqlar x²+y²=25 aylanaga urinma bo‘ladi?','["y=5 va y=−5","y=25 va y=−25","faqat y=0","y=√5 va y=−√5"]','Gorizontal urinma (0,0) markazdan radius 5 masofada yuqorida yoki pastda bo‘ladi, demak y=±5.',60),
('P1COO06-D03','P1-COO-06','diagnostic','hard','mcq','The line y=x+c is tangent to the circle x²+y²=8. Which values of c are possible?','["c=2 or c=−2","c=8 or c=−8","c=√8 only","c=4 or c=−4"]','D','Substitution gives 2x²+2cx+c²−8=0. Tangency requires discriminant 0: 4c²−8(c²−8)=0, so c²=16.','Прямая y=x+c касается окружности x²+y²=8. Какие значения c возможны?','["c=2 или c=−2","c=8 или c=−8","только c=√8","c=4 или c=−4"]','После подстановки получаем 2x²+2cx+c²−8=0. Для касания дискриминант равен 0: 4c²−8(c²−8)=0, поэтому c²=16.','y=x+c chiziq x²+y²=8 aylanaga urinma. c ning qaysi qiymatlari mumkin?','["c=2 yoki c=−2","c=8 yoki c=−8","faqat c=√8","c=4 yoki c=−4"]','Qo‘yishdan 2x²+2cx+c²−8=0 hosil bo‘ladi. Urinma uchun diskriminant 0: 4c²−8(c²−8)=0, demak c²=16.',85),
('P1COO06-R03','P1-COO-06','retest','medium','input','The line y=x+c is tangent to the circle x²+y²=2. Enter the positive value of c.','[]','2','The distance from (0,0) to x−y+c=0 is |c|/√2. Set this equal to radius √2: |c|=2, so the positive value is 2.','Прямая y=x+c касается окружности x²+y²=2. Введите положительное значение c.','[]','Расстояние от (0,0) до x−y+c=0 равно |c|/√2. Приравниваем к радиусу √2: |c|=2, поэтому положительное значение 2.','y=x+c chiziq x²+y²=2 aylanaga urinma. c ning musbat qiymatini kiriting.','[]','(0,0) dan x−y+c=0 gacha masofa |c|/√2. Uni radius √2 ga tenglaymiz: |c|=2, musbat qiymat 2.',75),
('P1COO06-R04','P1-COO-06','retest','hard','mcq','The line y=2x+k is tangent to the circle x²+y²=20. What is k²?','["100","20","40","80"]','A','Substitution gives 5x²+4kx+k²−20=0. Tangency requires 16k²−20(k²−20)=0, giving k²=100.','Прямая y=2x+k касается окружности x²+y²=20. Чему равно k²?','["100","20","40","80"]','После подстановки получаем 5x²+4kx+k²−20=0. Для касания 16k²−20(k²−20)=0, откуда k²=100.','y=2x+k chiziq x²+y²=20 aylanaga urinma. k² nechaga teng?','["100","20","40","80"]','Qo‘yishdan 5x²+4kx+k²−20=0. Urinma uchun 16k²−20(k²−20)=0, bundan k²=100.',85),
('P1COO06-M02','P1-COO-06','mixed','hard','input','For the circle x²+y²=8, the tangent y=x+c has c>0. Enter c.','[]','4','The centre-to-line distance is c/√2 and the radius is √8=2√2. Hence c/√2=2√2, so c=4.','Для окружности x²+y²=8 касательная y=x+c имеет c>0. Введите c.','[]','Расстояние от центра до прямой равно c/√2, а радиус √8=2√2. Поэтому c/√2=2√2 и c=4.','x²+y²=8 aylana uchun y=x+c urinmada c>0. c ni kiriting.','[]','Markazdan chiziqqacha masofa c/√2, radius esa √8=2√2. Demak c/√2=2√2 va c=4.',85),
('P1DIF05-D02','P1-DIF-05','diagnostic','medium','mcq','A differentiable function has f′(x)=(x−1)(x−4). On which intervals is f increasing?','["1<x<4","x<4 only","x<1 or x>4","x>1 only"]','C','The derivative is positive outside its roots 1 and 4 and negative between them, so f increases for x<1 or x>4.','Для дифференцируемой функции f′(x)=(x−1)(x−4). На каких интервалах f возрастает?','["1<x<4","только x<4","x<1 или x>4","только x>1"]','Производная положительна вне корней 1 и 4 и отрицательна между ними, поэтому f возрастает при x<1 или x>4.','Differensiallanuvchi funksiya uchun f′(x)=(x−1)(x−4). f qaysi oraliqlarda o‘sadi?','["1<x<4","faqat x<4","x<1 yoki x>4","faqat x>1"]','Hosila 1 va 4 ildizlar tashqarisida musbat, ular orasida manfiy. Shuning uchun f x<1 yoki x>4 da o‘sadi.',65),
('P1DIF05-D03','P1-DIF-05','diagnostic','medium','mcq','A function has derivative f′(x)=6−2x. Where is the function increasing?','["x>3","x<3","x<6","x>6"]','B','Increasing means f′(x)>0. Solving 6−2x>0 gives x<3.','Производная функции f′(x)=6−2x. Где функция возрастает?','["x>3","x<3","x<6","x>6"]','Возрастание означает f′(x)>0. Из 6−2x>0 получаем x<3.','Funksiya hosilasi f′(x)=6−2x. Funksiya qayerda o‘sadi?','["x>3","x<3","x<6","x>6"]','O‘sish uchun f′(x)>0. 6−2x>0 dan x<3.',55),
('P1DIF05-R03','P1-DIF-05','retest','medium','input','A function has f′(x)=x²−9. Enter the length of the interval on which the function is decreasing.','[]','6','f′(x)<0 when −3<x<3. The interval length is 3−(−3)=6.','У функции f′(x)=x²−9. Введите длину интервала, на котором функция убывает.','[]','f′(x)<0 при −3<x<3. Длина интервала равна 3−(−3)=6.','Funksiya uchun f′(x)=x²−9. Funksiya kamayadigan oraliq uzunligini kiriting.','[]','f′(x)<0 bo‘lishi −3<x<3 da. Oraliq uzunligi 3−(−3)=6.',60),
('P1DIF05-R04','P1-DIF-05','retest','hard','mcq','A differentiable function has f′(x)=(x+2)(x−5). On which interval is f decreasing?','["x<−2 or x>5","x>5","−2<x<5","x<−2"]','C','The product is negative between the roots −2 and 5, so the function decreases on −2<x<5.','Для дифференцируемой функции f′(x)=(x+2)(x−5). На каком интервале f убывает?','["x<−2 или x>5","x>5","−2<x<5","x<−2"]','Произведение отрицательно между корнями −2 и 5, поэтому функция убывает на −2<x<5.','Differensiallanuvchi funksiya uchun f′(x)=(x+2)(x−5). f qaysi oraliqda kamayadi?','["x<−2 yoki x>5","x>5","−2<x<5","x<−2"]','Ko‘paytma −2 va 5 ildizlar orasida manfiy, shuning uchun funksiya −2<x<5 da kamayadi.',70),
('P1DIF05-M02','P1-DIF-05','mixed','hard','input','For f′(x)=3x²−12, enter the positive stationary x-value at which f changes from decreasing to increasing.','[]','2','f′(x)=3(x−2)(x+2). Its sign changes from negative to positive at x=2, so x=2 is the required point.','Для f′(x)=3x²−12 введите положительное стационарное значение x, где f переходит от убывания к возрастанию.','[]','f′(x)=3(x−2)(x+2). При x=2 знак меняется с отрицательного на положительный, поэтому нужно x=2.','f′(x)=3x²−12 uchun f kamayishdan o‘sishga o‘tadigan musbat statsionar x qiymatini kiriting.','[]','f′(x)=3(x−2)(x+2). x=2 da ishora manfiydan musbatga o‘zgaradi, demak javob x=2.',75),
('P1DIF06-D02','P1-DIF-06','diagnostic','medium','mcq','The radius r of a circle increases at 3 cm/s. What is dA/dt when r=4 cm?','["24π cm²/s","12π cm²/s","48π cm²/s","16π cm²/s"]','A','A=πr², so dA/dt=2πr·dr/dt=2π(4)(3)=24π cm²/s.','Радиус r окружности увеличивается со скоростью 3 см/с. Чему равно dA/dt при r=4 см?','["24π см²/с","12π см²/с","48π см²/с","16π см²/с"]','A=πr², поэтому dA/dt=2πr·dr/dt=2π(4)(3)=24π см²/с.','Aylana radiusi r 3 cm/s tezlikda ortmoqda. r=4 cm bo‘lganda dA/dt nechaga teng?','["24π cm²/s","12π cm²/s","48π cm²/s","16π cm²/s"]','A=πr², shuning uchun dA/dt=2πr·dr/dt=2π(4)(3)=24π cm²/s.',65),
('P1DIF06-D03','P1-DIF-06','diagnostic','medium','mcq','A cube has side length x cm and volume V=x³. If dx/dt=−0.5 cm/s, what is dV/dt when x=4 cm?','["−8 cm³/s","24 cm³/s","−24 cm³/s","−32 cm³/s"]','C','dV/dt=3x² dx/dt=3(16)(−0.5)=−24 cm³/s. The negative sign shows the volume is decreasing.','Куб имеет ребро x см и объём V=x³. Если dx/dt=−0,5 см/с, чему равно dV/dt при x=4 см?','["−8 см³/с","24 см³/с","−24 см³/с","−32 см³/с"]','dV/dt=3x² dx/dt=3(16)(−0,5)=−24 см³/с. Отрицательный знак показывает уменьшение объёма.','Kub qirrasi x cm, hajmi V=x³. Agar dx/dt=−0.5 cm/s bo‘lsa, x=4 cm da dV/dt nechaga teng?','["−8 cm³/s","24 cm³/s","−24 cm³/s","−32 cm³/s"]','dV/dt=3x² dx/dt=3(16)(−0.5)=−24 cm³/s. Manfiy ishora hajm kamayishini ko‘rsatadi.',65),
('P1DIF06-R03','P1-DIF-06','retest','medium','input','A circle has circumference C=2πr and dr/dt=1.5 cm/s. Enter the coefficient of π in dC/dt.','[]','3','dC/dt=2π dr/dt=2π(1.5)=3π, so the coefficient is 3.','Для окружности C=2πr и dr/dt=1,5 см/с. Введите коэффициент при π в dC/dt.','[]','dC/dt=2π dr/dt=2π(1,5)=3π, поэтому коэффициент равен 3.','Aylana uchun C=2πr va dr/dt=1.5 cm/s. dC/dt dagi π koeffitsiyentini kiriting.','[]','dC/dt=2π dr/dt=2π(1.5)=3π, demak koeffitsiyent 3.',55),
('P1DIF06-R04','P1-DIF-06','retest','hard','mcq','A sphere has radius r cm. If dr/dt=0.2 cm/s, what is dV/dt when r=5 cm?','["20π cm³/s","10π cm³/s","25π cm³/s","100π cm³/s"]','A','V=4πr³/3, so dV/dt=4πr² dr/dt=4π(25)(0.2)=20π cm³/s.','Сфера имеет радиус r см. Если dr/dt=0,2 см/с, чему равно dV/dt при r=5 см?','["20π см³/с","10π см³/с","25π см³/с","100π см³/с"]','V=4πr³/3, поэтому dV/dt=4πr² dr/dt=4π(25)(0,2)=20π см³/с.','Sfera radiusi r cm. Agar dr/dt=0.2 cm/s bo‘lsa, r=5 cm da dV/dt nechaga teng?','["20π cm³/s","10π cm³/s","25π cm³/s","100π cm³/s"]','V=4πr³/3, demak dV/dt=4πr² dr/dt=4π(25)(0.2)=20π cm³/s.',75),
('P1DIF06-M02','P1-DIF-06','mixed','hard','input','A cone keeps h=2r, so V=(2/3)πr³. If dr/dt=0.3 cm/s, enter the coefficient of π in dV/dt when r=5 cm.','[]','15','dV/dt=2πr² dr/dt=2π(25)(0.3)=15π, so the coefficient is 15.','Для конуса всегда h=2r, поэтому V=(2/3)πr³. Если dr/dt=0,3 см/с, введите коэффициент при π в dV/dt при r=5 см.','[]','dV/dt=2πr² dr/dt=2π(25)(0,3)=15π, поэтому коэффициент 15.','Konusda doim h=2r, shuning uchun V=(2/3)πr³. Agar dr/dt=0.3 cm/s bo‘lsa, r=5 cm da dV/dt dagi π koeffitsiyentini kiriting.','[]','dV/dt=2πr² dr/dt=2π(25)(0.3)=15π, demak koeffitsiyent 15.',80),
('P1DIF07-D02','P1-DIF-07','diagnostic','hard','mcq','For f(x)=x³−3x²−9x, the stationary x-values are −1 and 3. Which x-value gives the local minimum?','["-1","3","0","1"]','B','f″(x)=6x−6. At x=3, f″(3)=12>0, so x=3 is a local minimum.','Для f(x)=x³−3x²−9x стационарные значения x равны −1 и 3. Какое значение x даёт локальный минимум?','["-1","3","0","1"]','f″(x)=6x−6. При x=3: f″(3)=12>0, поэтому x=3 — локальный минимум.','f(x)=x³−3x²−9x uchun statsionar x qiymatlar −1 va 3. Qaysi x lokal minimum beradi?','["-1","3","0","1"]','f″(x)=6x−6. x=3 da f″(3)=12>0, demak x=3 lokal minimum.',75),
('P1DIF07-D03','P1-DIF-07','diagnostic','medium','mcq','For f(x)=x²−8x+11, at which x-value does the minimum occur?','["2","8","-4","4"]','D','f′(x)=2x−8=0 gives x=4, and f″(x)=2>0, so this is the minimum.','Для f(x)=x²−8x+11 при каком x достигается минимум?','["2","8","-4","4"]','f′(x)=2x−8=0 даёт x=4, а f″(x)=2>0, поэтому это минимум.','f(x)=x²−8x+11 uchun minimum qaysi x da bo‘ladi?','["2","8","-4","4"]','f′(x)=2x−8=0 dan x=4, f″(x)=2>0, demak bu minimum.',55),
('P1DIF07-R03','P1-DIF-07','retest','medium','input','For y=x³−6x²+9x, enter the x-coordinate of the local maximum.','[]','1','y′=3(x−1)(x−3), so stationary points are x=1 and x=3. y″=6x−12 is negative at x=1, so the local maximum is at x=1.','Для y=x³−6x²+9x введите x-координату локального максимума.','[]','y′=3(x−1)(x−3), поэтому стационарные точки x=1 и x=3. y″=6x−12 отрицательна при x=1, значит локальный максимум при x=1.','y=x³−6x²+9x uchun lokal maksimumning x-koordinatasini kiriting.','[]','y′=3(x−1)(x−3), statsionar nuqtalar x=1 va x=3. y″=6x−12 x=1 da manfiy, demak lokal maksimum x=1 da.',70),
('P1DIF07-R04','P1-DIF-07','retest','hard','mcq','A rectangle has perimeter 20. If one side is x, its area is A=x(10−x). Which x gives the maximum area?','["2","5","4","10"]','B','A=10x−x², so A′=10−2x=0 gives x=5. Since A″=−2<0, this is a maximum.','Периметр прямоугольника равен 20. Если одна сторона x, то площадь A=x(10−x). Какое x даёт максимальную площадь?','["2","5","4","10"]','A=10x−x², поэтому A′=10−2x=0 даёт x=5. Так как A″=−2<0, это максимум.','To‘g‘ri to‘rtburchak perimetri 20. Bir tomoni x bo‘lsa, yuza A=x(10−x). Qaysi x maksimal yuzani beradi?','["2","5","4","10"]','A=10x−x², shuning uchun A′=10−2x=0 dan x=5. A″=−2<0 bo‘lgani uchun bu maksimum.',70),
('P1DIF07-M02','P1-DIF-07','mixed','hard','input','For x>0, y=12x−x³. Enter the x-value at which y is maximised.','[]','2','y′=12−3x²=0 gives x=2 for x>0. y″=−6x<0 at x=2, so it is a maximum.','При x>0 задано y=12x−x³. Введите значение x, при котором y максимально.','[]','y′=12−3x²=0 даёт x=2 при x>0. y″=−6x<0 при x=2, поэтому это максимум.','x>0 da y=12x−x³. y maksimal bo‘ladigan x qiymatini kiriting.','[]','y′=12−3x²=0 dan x>0 uchun x=2. x=2 da y″=−6x<0, demak bu maksimum.',70),
('P1INT01-D02','P1-INT-01','diagnostic','medium','mcq','Which is an antiderivative of 6x²−4x+3?','["2x³−4x²+3x+C","6x³−2x²+3+C","2x³−2x+3x²+C","2x³−2x²+3x+C"]','D','Integrate term by term: ∫6x²dx=2x³, ∫−4x dx=−2x² and ∫3dx=3x.','Какая функция является первообразной для 6x²−4x+3?','["2x³−4x²+3x+C","6x³−2x²+3+C","2x³−2x+3x²+C","2x³−2x²+3x+C"]','Интегрируем по членам: ∫6x²dx=2x³, ∫−4x dx=−2x² и ∫3dx=3x.','6x²−4x+3 uchun qaysi funksiya boshlang‘ich funksiya?','["2x³−4x²+3x+C","6x³−2x²+3+C","2x³−2x+3x²+C","2x³−2x²+3x+C"]','Hadma-had integrallaymiz: ∫6x²dx=2x³, ∫−4x dx=−2x² va ∫3dx=3x.',60),
('P1INT01-D03','P1-INT-01','diagnostic','hard','mcq','Which is an antiderivative of 4(2x+1)³?','["(2x+1)⁴/4+C","(2x+1)⁴/2+C","2(2x+1)⁴+C","4(2x+1)⁴+C"]','B','Let u=2x+1. Then dx=du/2, so ∫4u³dx=2∫u³du=u⁴/2+C.','Какая функция является первообразной для 4(2x+1)³?','["(2x+1)⁴/4+C","(2x+1)⁴/2+C","2(2x+1)⁴+C","4(2x+1)⁴+C"]','Пусть u=2x+1. Тогда dx=du/2, поэтому ∫4u³dx=2∫u³du=u⁴/2+C.','4(2x+1)³ uchun qaysi funksiya boshlang‘ich funksiya?','["(2x+1)⁴/4+C","(2x+1)⁴/2+C","2(2x+1)⁴+C","4(2x+1)⁴+C"]','u=2x+1 deb olamiz. dx=du/2, demak ∫4u³dx=2∫u³du=u⁴/2+C.',75),
('P1INT01-R03','P1-INT-01','retest','medium','input','In ∫15x⁴ dx, enter the coefficient of x⁵ in the antiderivative.','[]','3','∫15x⁴dx=3x⁵+C, so the coefficient is 3.','В ∫15x⁴ dx введите коэффициент при x⁵ в первообразной.','[]','∫15x⁴dx=3x⁵+C, поэтому коэффициент равен 3.','∫15x⁴ dx da boshlang‘ich funksiyadagi x⁵ koeffitsiyentini kiriting.','[]','∫15x⁴dx=3x⁵+C, demak koeffitsiyent 3.',45),
('P1INT01-R04','P1-INT-01','retest','hard','mcq','Which is an antiderivative of (3x−2)²?','["(3x−2)³/3+C","3(3x−2)³+C","(3x−2)³+C","(3x−2)³/9+C"]','D','For ∫(3x−2)²dx, divide by the inner derivative 3 and the new power 3: (3x−2)³/9+C.','Какая функция является первообразной для (3x−2)²?','["(3x−2)³/3+C","3(3x−2)³+C","(3x−2)³+C","(3x−2)³/9+C"]','Для ∫(3x−2)²dx делим на внутреннюю производную 3 и новую степень 3: (3x−2)³/9+C.','(3x−2)² uchun qaysi funksiya boshlang‘ich funksiya?','["(3x−2)³/3+C","3(3x−2)³+C","(3x−2)³+C","(3x−2)³/9+C"]','∫(3x−2)²dx uchun ichki hosila 3 va yangi daraja 3 ga bo‘lamiz: (3x−2)³/9+C.',70),
('P1INT01-M02','P1-INT-01','mixed','hard','input','An antiderivative of 8x³ contains the term ax⁴. Enter a.','[]','2','∫8x³dx=2x⁴+C, so a=2.','Первообразная для 8x³ содержит член ax⁴. Введите a.','[]','∫8x³dx=2x⁴+C, поэтому a=2.','8x³ ning boshlang‘ich funksiyasi ax⁴ hadini o‘z ichiga oladi. a ni kiriting.','[]','∫8x³dx=2x⁴+C, demak a=2.',45),
('P1INT02-D02','P1-INT-02','diagnostic','medium','mcq','A curve has dy/dx=6x−4 and passes through (1,5). What is the constant C in y=3x²−4x+C?','["4","5","6","7"]','C','At x=1, y=3−4+C=C−1=5, so C=6.','Кривая имеет dy/dx=6x−4 и проходит через (1,5). Чему равна константа C в y=3x²−4x+C?','["4","5","6","7"]','При x=1: y=3−4+C=C−1=5, поэтому C=6.','Egri chiziqda dy/dx=6x−4 va u (1,5) nuqtadan o‘tadi. y=3x²−4x+C dagi C nechaga teng?','["4","5","6","7"]','x=1 da y=3−4+C=C−1=5, demak C=6.',55),
('P1INT02-D03','P1-INT-02','diagnostic','medium','mcq','A curve satisfies dy/dx=3x²+2 and y=−4 when x=0. What is y when x=2?','["10","12","4","8"]','D','Integrating gives y=x³+2x+C. Since y(0)=−4, C=−4. Thus y(2)=8+4−4=8.','Кривая удовлетворяет dy/dx=3x²+2 и y=−4 при x=0. Чему равно y при x=2?','["10","12","4","8"]','После интегрирования y=x³+2x+C. Так как y(0)=−4, C=−4. Тогда y(2)=8+4−4=8.','Egri chiziq dy/dx=3x²+2 shartini qanoatlantiradi va x=0 da y=−4. x=2 da y nechaga teng?','["10","12","4","8"]','Integrallashdan y=x³+2x+C. y(0)=−4 bo‘lgani uchun C=−4. Demak y(2)=8+4−4=8.',65),
('P1INT02-R03','P1-INT-02','retest','medium','input','A curve has dy/dx=4x+1 and passes through (2,7). In y=2x²+x+C, enter C.','[]','-3','At (2,7), 7=2(4)+2+C=10+C, so C=−3.','Кривая имеет dy/dx=4x+1 и проходит через (2,7). В y=2x²+x+C введите C.','[]','В точке (2,7): 7=2(4)+2+C=10+C, поэтому C=−3.','Egri chiziqda dy/dx=4x+1 va u (2,7) nuqtadan o‘tadi. y=2x²+x+C da C ni kiriting.','[]','(2,7) nuqtada 7=2(4)+2+C=10+C, demak C=−3.',55),
('P1INT02-R04','P1-INT-02','retest','hard','mcq','A curve has dy/dx=12x²−6x and passes through (1,4). What is the constant C in y=4x³−3x²+C?','["1","3","4","-3"]','B','At x=1, 4=4−3+C=1+C, so C=3.','Кривая имеет dy/dx=12x²−6x и проходит через (1,4). Чему равна C в y=4x³−3x²+C?','["1","3","4","-3"]','При x=1: 4=4−3+C=1+C, поэтому C=3.','Egri chiziqda dy/dx=12x²−6x va u (1,4) nuqtadan o‘tadi. y=4x³−3x²+C dagi C nechaga teng?','["1","3","4","-3"]','x=1 da 4=4−3+C=1+C, demak C=3.',60),
('P1INT02-M02','P1-INT-02','mixed','hard','input','A curve has dy/dx=5x⁴ and y=7 when x=1. Enter y when x=2.','[]','38','Integrating gives y=x⁵+C. From y(1)=7, C=6. Hence y(2)=32+6=38.','Кривая имеет dy/dx=5x⁴ и y=7 при x=1. Введите y при x=2.','[]','Интегрирование даёт y=x⁵+C. Из y(1)=7 получаем C=6. Поэтому y(2)=32+6=38.','Egri chiziqda dy/dx=5x⁴ va x=1 da y=7. x=2 da y ni kiriting.','[]','Integrallashdan y=x⁵+C. y(1)=7 dan C=6. Demak y(2)=32+6=38.',65),
('P1INT03-D02','P1-INT-03','diagnostic','medium','mcq','Evaluate ∫ from 1 to 3 of 2x dx.','["6","4","9","8"]','D','An antiderivative is x². Therefore 3²−1²=9−1=8.','Вычислите ∫ от 1 до 3 от 2x dx.','["6","4","9","8"]','Первообразная — x². Поэтому 3²−1²=9−1=8.','1 dan 3 gacha ∫2x dx ni hisoblang.','["6","4","9","8"]','Boshlang‘ich funksiya x². Shuning uchun 3²−1²=9−1=8.',50),
('P1INT03-D03','P1-INT-03','diagnostic','medium','mcq','Evaluate ∫ from 0 to 2 of (3x²+1) dx.','["8","12","10","6"]','C','An antiderivative is x³+x. Evaluating from 0 to 2 gives 8+2=10.','Вычислите ∫ от 0 до 2 от (3x²+1) dx.','["8","12","10","6"]','Первообразная — x³+x. Подстановка пределов 0 и 2 даёт 8+2=10.','0 dan 2 gacha ∫(3x²+1) dx ni hisoblang.','["8","12","10","6"]','Boshlang‘ich funksiya x³+x. 0 va 2 chegaralarda qiymat 8+2=10.',55),
('P1INT03-R03','P1-INT-03','retest','medium','input','Evaluate ∫ from −1 to 2 of (2x+3) dx. Enter the exact value.','[]','12','An antiderivative is x²+3x. Its value is 10 at x=2 and −2 at x=−1, so the integral is 10−(−2)=12.','Вычислите ∫ от −1 до 2 от (2x+3) dx. Введите точное значение.','[]','Первообразная x²+3x. При x=2 она равна 10, при x=−1 равна −2, поэтому интеграл 10−(−2)=12.','−1 dan 2 gacha ∫(2x+3) dx ni hisoblang. Aniq qiymatni kiriting.','[]','Boshlang‘ich funksiya x²+3x. x=2 da 10, x=−1 da −2, demak integral 10−(−2)=12.',60),
('P1INT03-R04','P1-INT-03','retest','hard','mcq','Evaluate ∫ from 0 to 1 of (4x³−2x) dx.','["0","1","-1","2"]','A','An antiderivative is x⁴−x². At both 1 and 0 the required difference is 0, so the integral is 0.','Вычислите ∫ от 0 до 1 от (4x³−2x) dx.','["0","1","-1","2"]','Первообразная x⁴−x². Разность значений при 1 и 0 равна 0, поэтому интеграл равен 0.','0 dan 1 gacha ∫(4x³−2x) dx ni hisoblang.','["0","1","-1","2"]','Boshlang‘ich funksiya x⁴−x². 1 va 0 dagi qiymatlar farqi 0, demak integral 0.',60),
('P1INT03-M02','P1-INT-03','mixed','hard','input','Evaluate the improper endpoint integral ∫ from 0 to 4 of x^(−1/2) dx. Enter the exact value.','[]','4','Use the limit at 0. An antiderivative is 2√x, so the value is 2√4−lim(a→0+)2√a=4.','Вычислите несобственный интеграл с особой конечной точкой ∫ от 0 до 4 от x^(−1/2) dx. Введите точное значение.','[]','Используем предел при 0. Первообразная 2√x, поэтому значение 2√4−lim(a→0+)2√a=4.','0 dan 4 gacha x^(−1/2) dx ning chekka nuqtadagi xosmas integralini hisoblang. Aniq qiymatni kiriting.','[]','0 dagi limitdan foydalanamiz. Boshlang‘ich funksiya 2√x, demak 2√4−lim(a→0+)2√a=4.',80),
('P1INT04-D02','P1-INT-04','diagnostic','medium','mcq','Find the area under y=6x−x² from x=0 to x=6.','["18","36","24","72"]','B','The curve is non-negative on [0,6]. ∫₀⁶(6x−x²)dx=[3x²−x³/3]₀⁶=108−72=36.','Найдите площадь под графиком y=6x−x² от x=0 до x=6.','["18","36","24","72"]','На [0,6] функция неотрицательна. ∫₀⁶(6x−x²)dx=[3x²−x³/3]₀⁶=108−72=36.','y=6x−x² grafigi ostidagi x=0 dan x=6 gacha yuzani toping.','["18","36","24","72"]','[0,6] da funksiya manfiy emas. ∫₀⁶(6x−x²)dx=[3x²−x³/3]₀⁶=108−72=36.',70),
('P1INT04-D03','P1-INT-04','diagnostic','hard','mcq','Find the area between y=x+2 and y=x² for 0≤x≤2.','["10/3","4/3","8/3","14/3"]','A','On [0,2], x+2 is above x². The area is ∫₀²(x+2−x²)dx=[x²/2+2x−x³/3]₀²=10/3.','Найдите площадь между y=x+2 и y=x² при 0≤x≤2.','["10/3","4/3","8/3","14/3"]','На [0,2] график x+2 выше x². Площадь ∫₀²(x+2−x²)dx=[x²/2+2x−x³/3]₀²=10/3.','0≤x≤2 da y=x+2 va y=x² orasidagi yuzani toping.','["10/3","4/3","8/3","14/3"]','[0,2] da x+2 grafigi x² dan yuqori. Yuza ∫₀²(x+2−x²)dx=[x²/2+2x−x³/3]₀²=10/3.',75),
('P1INT04-R03','P1-INT-04','retest','medium','input','Find the total area between y=x²−4 and the x-axis for −2≤x≤2. Enter the exact value.','[]','32/3','The curve is below the axis inside [−2,2], so area=∫₋₂²(4−x²)dx=32/3.','Найдите полную площадь между y=x²−4 и осью x при −2≤x≤2. Введите точное значение.','[]','На [−2,2] график ниже оси, поэтому площадь =∫₋₂²(4−x²)dx=32/3.','−2≤x≤2 da y=x²−4 va x-o‘qi orasidagi umumiy yuzani toping. Aniq qiymatni kiriting.','[]','[−2,2] da grafik o‘qdan pastda, shuning uchun yuza=∫₋₂²(4−x²)dx=32/3.',70),
('P1INT04-R04','P1-INT-04','retest','hard','mcq','Find the area between y=x and y=x² for 0≤x≤1.','["1/3","1/2","2/3","1/6"]','D','On [0,1], x≥x². Area=∫₀¹(x−x²)dx=1/2−1/3=1/6.','Найдите площадь между y=x и y=x² при 0≤x≤1.','["1/3","1/2","2/3","1/6"]','На [0,1] x≥x². Площадь =∫₀¹(x−x²)dx=1/2−1/3=1/6.','0≤x≤1 da y=x va y=x² orasidagi yuzani toping.','["1/3","1/2","2/3","1/6"]','[0,1] da x≥x². Yuza=∫₀¹(x−x²)dx=1/2−1/3=1/6.',60),
('P1INT04-M02','P1-INT-04','mixed','hard','input','Find the total area between y=x²−1 and the x-axis for −2≤x≤2. Enter the exact value.','[]','4','Split at x=−1 and x=1. By symmetry, total area=2[∫₀¹(1−x²)dx+∫₁²(x²−1)dx]=2(2/3+4/3)=4.','Найдите полную площадь между y=x²−1 и осью x при −2≤x≤2. Введите точное значение.','[]','Разбиваем в x=−1 и x=1. По симметрии полная площадь =2[∫₀¹(1−x²)dx+∫₁²(x²−1)dx]=2(2/3+4/3)=4.','−2≤x≤2 da y=x²−1 va x-o‘qi orasidagi umumiy yuzani toping. Aniq qiymatni kiriting.','[]','x=−1 va x=1 da bo‘lamiz. Simmetriya bo‘yicha umumiy yuza=2[∫₀¹(1−x²)dx+∫₁²(x²−1)dx]=2(2/3+4/3)=4.',85),
('P1INT05-D02','P1-INT-05','diagnostic','medium','mcq','The region under y=x from x=0 to x=2 is rotated about the x-axis. What volume is formed?','["8π/3","4π/3","4π","8π"]','A','V=π∫₀²y²dx=π∫₀²x²dx=π[x³/3]₀²=8π/3.','Область под y=x от x=0 до x=2 вращают вокруг оси x. Какой объём получается?','["8π/3","4π/3","4π","8π"]','V=π∫₀²y²dx=π∫₀²x²dx=π[x³/3]₀²=8π/3.','y=x ostidagi x=0 dan x=2 gacha soha x-o‘qi atrofida aylantiriladi. Qanday hajm hosil bo‘ladi?','["8π/3","4π/3","4π","8π"]','V=π∫₀²y²dx=π∫₀²x²dx=π[x³/3]₀²=8π/3.',65),
('P1INT05-D03','P1-INT-05','diagnostic','medium','mcq','The region under y=2x from x=0 to x=1 is rotated about the x-axis. What is the volume?','["2π/3","π/3","4π/3","4π"]','C','V=π∫₀¹(2x)²dx=4π∫₀¹x²dx=4π/3.','Область под y=2x от x=0 до x=1 вращают вокруг оси x. Чему равен объём?','["2π/3","π/3","4π/3","4π"]','V=π∫₀¹(2x)²dx=4π∫₀¹x²dx=4π/3.','y=2x ostidagi x=0 dan x=1 gacha soha x-o‘qi atrofida aylantiriladi. Hajm nechaga teng?','["2π/3","π/3","4π/3","4π"]','V=π∫₀¹(2x)²dx=4π∫₀¹x²dx=4π/3.',60),
('P1INT05-R03','P1-INT-05','retest','medium','input','The region under y=√x from x=0 to x=4 is rotated about the x-axis. Enter the coefficient of π in the volume.','[]','8','V=π∫₀⁴y²dx=π∫₀⁴x dx=π[x²/2]₀⁴=8π, so the coefficient is 8.','Область под y=√x от x=0 до x=4 вращают вокруг оси x. Введите коэффициент при π в объёме.','[]','V=π∫₀⁴y²dx=π∫₀⁴x dx=π[x²/2]₀⁴=8π, поэтому коэффициент 8.','y=√x ostidagi x=0 dan x=4 gacha soha x-o‘qi atrofida aylantiriladi. Hajmdagi π koeffitsiyentini kiriting.','[]','V=π∫₀⁴y²dx=π∫₀⁴x dx=π[x²/2]₀⁴=8π, demak koeffitsiyent 8.',65),
('P1INT05-R04','P1-INT-05','retest','hard','mcq','The region under y=x+1 for 0≤x≤1 is rotated about the x-axis. What is the volume?','["3π","7π/3","8π/3","2π"]','B','V=π∫₀¹(x+1)²dx=π[(x+1)³/3]₀¹=π(8/3−1/3)=7π/3.','Область под y=x+1 при 0≤x≤1 вращают вокруг оси x. Чему равен объём?','["3π","7π/3","8π/3","2π"]','V=π∫₀¹(x+1)²dx=π[(x+1)³/3]₀¹=π(8/3−1/3)=7π/3.','0≤x≤1 da y=x+1 ostidagi soha x-o‘qi atrofida aylantiriladi. Hajm nechaga teng?','["3π","7π/3","8π/3","2π"]','V=π∫₀¹(x+1)²dx=π[(x+1)³/3]₀¹=π(8/3−1/3)=7π/3.',70),
('P1INT05-M02','P1-INT-05','mixed','hard','input','The region y=3, 0≤x≤2, above the x-axis is rotated about the x-axis. Enter the coefficient of π in the volume.','[]','18','V=π∫₀²3²dx=9π(2)=18π, so the coefficient is 18.','Область y=3, 0≤x≤2, над осью x вращают вокруг оси x. Введите коэффициент при π в объёме.','[]','V=π∫₀²3²dx=9π(2)=18π, поэтому коэффициент 18.','y=3, 0≤x≤2 soha x-o‘qi ustida joylashgan va x-o‘qi atrofida aylantiriladi. Hajmdagi π koeffitsiyentini kiriting.','[]','V=π∫₀²3²dx=9π(2)=18π, demak koeffitsiyent 18.',55)
)
